mapper.insert:
INSERT INTO bt_intention_embedding (id, tenant_id, question_id, question, created_time) VALUES
( #{dto.id}, #{dto.tenantId}, #{dto.questionId}, #{dto.question,typeHandler=org.apache.ibatis.type.UnknownTypeHandler},
)

mapper.select:
SELECT id
FROM bt_intention_embedding
WHERE question_id = #{questionId}

SELECT a.question_id, (2 - (a.question <=> #{question}::halfvec)) / 2 AS score FROM bt_intention_embedding a LEFT JOIN bt_intention_question b ON a.question_id = b.question_id AND a.tenant_id = b.tenant_id LEFT JOIN bt_bot_scene c ON b.scene_id = c.scene_id AND b.tenant_id = c.tenant_id WHERE a.tenant_id = #{tenantId} AND c.status_cd = '00A' AND c.scene_status = '1'
AND EXISTS (SELECT 1 FROM bt_bot_scene_rel r WHERE c.scene_id = r.scene_id AND c.tenant_id = r.tenant_id AND r.status_cd = '00A' AND r.bot_id = #{botId})
AND (2 - (a.question <=> #{question}::halfvec)) / 2 > #{minScore} ORDER BY score DESC #{topNum}
